 WHEN (p_key,p_current_version,p_current_digest,p_version,p_digest)=('jira-server-dc','1.2.0','6b9ae7ef7c96c6a80187a84d52239673c3818e490db89f72dca75e38efdfbd8f','1.1.0','fc35495f83ec21d3698c1e7cfa37eec1075ad35dd30b9dd7f9f680acf989cb31') THEN $caps$[{"allowedApprovalPolicies":["NONE"],"approvalPolicy":"NONE","key":"jira.identity.read","name":"Проверить текущую учётную запись","operation":"jira.identity.read","resourceKind":"JIRA_PROJECT","risk":"READ"},{"allowedApprovalPolicies":["NONE"],"approvalPolicy":"NONE","key":"jira.project.read","name":"Прочитать проект Jira","operation":"jira.project.read","resourceKind":"JIRA_PROJECT","risk":"READ"},{"allowedApprovalPolicies":["NONE"],"approvalPolicy":"NONE","key":"jira.issue.search","name":"Найти задачи","operation":"jira.issue.search","resourceKind":"JIRA_PROJECT","risk":"READ"},{"allowedApprovalPolicies":["NONE"],"approvalPolicy":"NONE","key":"jira.issue.read","name":"Прочитать задачу","operation":"jira.issue.read","resourceKind":"JIRA_PROJECT","risk":"READ"},{"allowedApprovalPolicies":["HUMAN_EACH_EFFECT"],"approvalPolicy":"HUMAN_EACH_EFFECT","key":"jira.issue.create","name":"Создать задачу","operation":"jira.issue.create","resourceKind":"JIRA_PROJECT","risk":"WRITE"},{"allowedApprovalPolicies":["HUMAN_EACH_EFFECT"],"approvalPolicy":"HUMAN_EACH_EFFECT","key":"jira.issue.comment.write","name":"Добавить комментарий","operation":"jira.issue.comment.write","resourceKind":"JIRA_PROJECT","risk":"WRITE"},{"allowedApprovalPolicies":["NONE"],"approvalPolicy":"NONE","key":"jira.issue.transition.list","name":"Получить доступные переходы issue","operation":"jira.issue.transition.list","resourceKind":"JIRA_PROJECT","risk":"READ"},{"allowedApprovalPolicies":["HUMAN_EACH_EFFECT"],"approvalPolicy":"HUMAN_EACH_EFFECT","key":"jira.issue.transition.apply","name":"Выполнить переход issue","operation":"jira.issue.transition.apply","resourceKind":"JIRA_PROJECT","risk":"WRITE"}]$caps$::jsonb
 ELSE NULL::jsonb END;
