-- +goose StatementEnd
REVOKE ALL ON FUNCTION control_plane.integration_policy_legacy_capabilities(text,text,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION control_plane.integration_policy_legacy_capabilities(text,text,text,text,text) TO control_plane_runtime;

-- +goose StatementBegin
DO $historical_admission$
DECLARE
 v_signature regprocedure := 'control_plane.integration_grant_admission(uuid,uuid,uuid,text,text,text,text,text,text,text[])'::regprocedure;
 v_definition text;
 v_before text := $before$                ELSE (
                    SELECT revision.content::jsonb #> '{spec,capabilities}'$before$;
 v_after text := $after$                WHEN control_plane.integration_policy_legacy_capabilities(connection.definition_key,
                    definition.definition_version,definition.digest,connection.definition_version,connection.definition_digest) IS NOT NULL
                THEN control_plane.integration_policy_legacy_capabilities(connection.definition_key,
                    definition.definition_version,definition.digest,connection.definition_version,connection.definition_digest)
                ELSE (
                    SELECT revision.content::jsonb #> '{spec,capabilities}'$after$;
BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_proc WHERE oid=v_signature AND pg_get_userbyid(proowner)='control_plane_owner' AND NOT prosecdef)
 THEN RAISE EXCEPTION 'integration policy admission predecessor owner changed'; END IF;
 v_definition := pg_get_functiondef(v_signature);
 IF (length(v_definition)-length(replace(v_definition,v_before,'')))/length(v_before)<>1
 THEN RAISE EXCEPTION 'integration policy admission predecessor changed'; END IF;
 EXECUTE replace(v_definition,v_before,v_after);
END $historical_admission$;
-- +goose StatementEnd

-- Пакет берётся только из current exact pin, closed historical registry либо
-- опубликованной owner binding с проверкой полного canonical content digest.
-- +goose StatementBegin
CREATE FUNCTION control_plane.integration_pinned_capabilities(p_connection uuid)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,control_plane AS $pinned$
 SELECT CASE WHEN (c.definition_version,c.definition_digest)=(d.definition_version,d.digest) THEN d.capabilities
 ELSE COALESCE(control_plane.integration_policy_legacy_capabilities(c.definition_key,d.definition_version,d.digest,c.definition_version,c.definition_digest),(
  SELECT revision.content::jsonb #> '{spec,capabilities}'
  FROM control_plane.managed_configuration_bindings binding
  JOIN control_plane.managed_configuration_sets configuration ON configuration.id=binding.configuration_set_id AND configuration.organization_id=binding.organization_id
  JOIN control_plane.managed_configuration_revisions revision ON revision.id=binding.configuration_revision_id AND revision.organization_id=binding.organization_id AND revision.configuration_set_id=configuration.id
  WHERE binding.organization_id=c.organization_id AND binding.consumer_kind='INTEGRATION_CONNECTION' AND binding.consumer_ref=c.ref
    AND binding.configuration_kind='INTEGRATION_DEFINITION' AND configuration.kind='INTEGRATION_DEFINITION'
    AND revision.state='PUBLISHED' AND revision.content_format='JSON'
    AND encode(public.digest(convert_to(revision.content,'UTF8'),'sha256'),'hex')=c.definition_digest
    AND revision.content::jsonb #>> '{metadata,key}'=c.definition_key AND revision.content::jsonb #>> '{metadata,version}'=c.definition_version
 )) END
 FROM control_plane.integration_connections c JOIN control_plane.integration_definitions d ON d.stable_key=c.definition_key
 WHERE c.id=p_connection;
$pinned$;
-- +goose StatementEnd
REVOKE ALL ON FUNCTION control_plane.integration_pinned_capabilities(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION control_plane.integration_pinned_capabilities(uuid) TO control_plane_runtime;

-- +goose StatementBegin
CREATE FUNCTION control_plane.integration_declared_policy_allowed(p_connection uuid,p_capability text,p_operation text,p_risk text,p_kind text,p_policy text,p_input jsonb)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,control_plane AS $policy$
 SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(control_plane.integration_pinned_capabilities(p_connection)) cap
  WHERE cap->>'key'=p_capability AND cap->>'operation'=p_operation AND cap->>'risk'=p_risk
   AND COALESCE(cap->>'resourceKind',cap #>> '{resourceScope,kind}')=p_kind
   AND COALESCE(cap->'allowedApprovalPolicies',jsonb_build_array(cap->>'approvalPolicy')) ? p_policy
   AND (p_policy<>'HUMAN_SCOPED' OR cap ? 'approvalScope' OR p_risk<>'READ')
   AND (p_policy<>'NONE' OR p_operation<>'github.pull_request.review.create' OR cap ? 'approvalScope' OR p_input->>'event'='COMMENT'));
$policy$;
-- +goose StatementEnd
REVOKE ALL ON FUNCTION control_plane.integration_declared_policy_allowed(uuid,text,text,text,text,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION control_plane.integration_declared_policy_allowed(uuid,text,text,text,text,text,jsonb) TO control_plane_runtime;

ALTER TABLE control_plane.integration_grants
 DROP CONSTRAINT integration_grants_approval_scope_paths_check,
 ADD CONSTRAINT integration_grants_approval_scope_paths_check CHECK (
  cardinality(approval_scope_paths)<=16 AND octet_length(array_to_string(approval_scope_paths,E'\x1f'))<=4096
  AND (approval_policy='HUMAN_SCOPED' OR cardinality(approval_scope_paths)=0)),
 DROP CONSTRAINT integration_grants_resource_kind_check,
 ADD CONSTRAINT integration_grants_resource_kind_check CHECK (resource_kind IN (
  'SYNTHETIC_JOURNAL','GITHUB_REPOSITORY','GITLAB_PROJECT','GITLAB_SCOPE','JIRA_PROJECT','CONFLUENCE_SPACE','EMAIL_SENDER','MATTERMOST_CHANNEL','HTTPS_RESOURCE','SSH_TARGET'));
ALTER TABLE control_plane.integration_invocations
 DROP CONSTRAINT integration_invocations_resource_kind_check,
 ADD CONSTRAINT integration_invocations_resource_kind_check CHECK (resource_kind IN (
  'SYNTHETIC_JOURNAL','GITHUB_REPOSITORY','GITLAB_PROJECT','GITLAB_SCOPE','JIRA_PROJECT','CONFLUENCE_SPACE','EMAIL_SENDER','MATTERMOST_CHANNEL','HTTPS_RESOURCE','SSH_TARGET')),
 DROP CONSTRAINT integration_invocations_approval_pins_check,
 ADD CONSTRAINT integration_invocations_approval_pins_check CHECK (
  (grant_version>0 AND ((approval_policy<>'HUMAN_SCOPED' AND cardinality(approval_scope_paths)=0) OR
   (approval_policy='HUMAN_SCOPED' AND cardinality(approval_scope_paths) BETWEEN 0 AND 16))) OR
  (grant_version=0 AND approval_policy<>'HUMAN_SCOPED' AND cardinality(approval_scope_paths)=0 AND state IN ('SUCCEEDED','FAILED','REJECTED','CANCELLED'))),
 DROP CONSTRAINT integration_invocations_approval_check,
 ADD CONSTRAINT integration_invocations_approval_check CHECK (
  approval_policy IN ('NONE','HUMAN_EACH_EFFECT','HUMAN_SCOPED')
  AND (approval_policy<>'NONE' OR state<>'WAITING_APPROVAL' OR mailbox_gate_required));
ALTER TABLE control_plane.integration_personal_invocation_credentials
 DROP CONSTRAINT integration_personal_invocati_resource_permission_profile_check,
 ADD CONSTRAINT integration_personal_invocati_resource_permission_profile_check CHECK
 (resource_permission_profile IN ('','CONFLUENCE_SERVER_PAGE_UPDATE_V1','JIRA_SERVER_ISSUE_CREATE_V1','JIRA_SERVER_COMMENT_WRITE_V1','JIRA_SERVER_TRANSITION_APPLY_V1',
 'GITLAB_PROJECT_OBJECT_READ_V1','JIRA_SERVER_PROJECT_OBJECT_READ_V1','CONFLUENCE_SERVER_SPACE_OBJECT_READ_V1',
 'GITLAB_PROJECT_ISSUE_CREATE_V1','GITLAB_PROJECT_BRANCH_CREATE_V1','GITLAB_PROJECT_MERGE_REQUEST_CREATE_V1','GITLAB_SCOPED_RESOURCE_V2'));

-- Политика неизменна после intent; опубликованный пакет проверяется на INSERT,
-- а claim/begin повторно проверяют current pins до допуска вызова.
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION control_plane.protect_email_mailbox_gate() RETURNS trigger LANGUAGE plpgsql AS $guard$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.mailbox_gate_required IS DISTINCT FROM OLD.mailbox_gate_required
  OR NEW.approval_policy IS DISTINCT FROM OLD.approval_policy OR NEW.grant_version IS DISTINCT FROM OLD.grant_version
  OR NEW.approval_scope_paths IS DISTINCT FROM OLD.approval_scope_paths) THEN
  RAISE EXCEPTION 'integration approval binding is immutable';
 END IF;
 IF NEW.mailbox_gate_required AND NOT EXISTS(SELECT 1 FROM control_plane.integration_connections c
   WHERE c.id=NEW.connection_id AND c.organization_id=NEW.organization_id AND c.definition_key='email') THEN
  RAISE EXCEPTION 'mailbox approval requires email owner connection';
 END IF;
 IF TG_OP='INSERT' AND NOT control_plane.integration_declared_policy_allowed(
   NEW.connection_id,NEW.capability_key,NEW.operation,NEW.risk,NEW.resource_kind,NEW.approval_policy,NEW.bounded_input) THEN
  RAISE EXCEPTION 'integration policy is not declared by pinned package';
 END IF;
 RETURN NEW;
END $guard$;
-- +goose StatementEnd

ALTER TABLE control_plane.integration_approval_scopes
 DROP CONSTRAINT integration_approval_scopes_scope_paths_check,
 ADD CONSTRAINT integration_approval_scopes_scope_paths_check CHECK (cardinality(scope_paths) BETWEEN 0 AND 16),
 DROP CONSTRAINT integration_approval_scopes_max_effects_check,
 ADD CONSTRAINT integration_approval_scopes_max_effects_check CHECK (max_effects BETWEEN 1 AND 10000),
 ADD COLUMN scope_lifetime text NOT NULL DEFAULT 'ROOT_RUN' CHECK (scope_lifetime IN ('ROOT_RUN','INITIATOR_RESOURCE')),
 ADD COLUMN initiator_id uuid,
 ADD COLUMN version bigint NOT NULL DEFAULT 1 CHECK (version>0),
 ADD CONSTRAINT integration_approval_scopes_initiator_check CHECK (scope_lifetime='ROOT_RUN' OR initiator_id IS NOT NULL);
CREATE INDEX integration_approval_scopes_initiator_idx ON control_plane.integration_approval_scopes
 (organization_id,initiator_id,created_at,id) WHERE initiator_id IS NOT NULL;

-- +goose StatementBegin
CREATE OR REPLACE FUNCTION control_plane.guard_integration_approval_scope_update() RETURNS trigger LANGUAGE plpgsql AS $scope_guard$
BEGIN
 IF (to_jsonb(NEW)-'reserved_effects'-'revoked_at'-'version') IS DISTINCT FROM (to_jsonb(OLD)-'reserved_effects'-'revoked_at'-'version')
  OR NEW.reserved_effects<OLD.reserved_effects OR NEW.version<>OLD.version
  OR (OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at)
  OR (NEW.reserved_effects>OLD.reserved_effects AND (OLD.revoked_at IS NOT NULL OR OLD.expires_at<=clock_timestamp())) THEN
  RAISE EXCEPTION 'integration approval scope binding is immutable';
 END IF;
 IF NEW.revoked_at IS DISTINCT FROM OLD.revoked_at THEN
  NEW.revoked_at=clock_timestamp(); NEW.version=OLD.version+1;
 END IF;
 RETURN NEW;
END $scope_guard$;
-- +goose StatementEnd

-- +goose StatementBegin
CREATE FUNCTION control_plane.guard_integration_approval_scope_insert() RETURNS trigger LANGUAGE plpgsql AS $scope_insert$
DECLARE cap jsonb; max_duration bigint; max_count bigint; lifetime_choices jsonb;
BEGIN
 IF NEW.version<>1 OR NEW.reserved_effects<>1 OR NEW.revoked_at IS NOT NULL OR NOT EXISTS(
  SELECT 1 FROM control_plane.runs root JOIN control_plane.subjects initiator ON initiator.id=root.initiated_by AND initiator.organization_id=root.organization_id
  JOIN control_plane.owner_gates gate ON gate.id=NEW.origin_gate_id AND gate.organization_id=root.organization_id AND gate.root_run_id=root.id AND gate.project_id IS NOT DISTINCT FROM NEW.project_id
  JOIN control_plane.integration_invocations invocation ON invocation.id=gate.integration_invocation_id AND invocation.organization_id=root.organization_id
  JOIN control_plane.run_nodes node ON node.id=invocation.node_id AND node.agent_id=NEW.agent_id
  WHERE root.id=NEW.root_run_id AND root.root_run_id=root.id AND root.organization_id=NEW.organization_id AND root.project_id IS NOT DISTINCT FROM NEW.project_id
   AND root.initiated_by=NEW.initiator_id AND gate.state='OPEN' AND invocation.state='WAITING_APPROVAL' AND invocation.approval_policy='HUMAN_SCOPED'
   AND invocation.connection_id=NEW.connection_id AND invocation.grant_id=NEW.grant_id AND invocation.grant_version=NEW.grant_version
   AND invocation.capability_key=NEW.capability_key AND invocation.definition_digest=NEW.definition_digest AND invocation.approval_scope_paths=NEW.scope_paths
   AND (NEW.scope_lifetime='ROOT_RUN' OR (initiator.kind='USER' AND initiator.active))
 ) THEN RAISE EXCEPTION 'integration approval scope owner binding is invalid'; END IF;
 SELECT value INTO cap FROM jsonb_array_elements(control_plane.integration_pinned_capabilities(NEW.connection_id)) value WHERE value->>'key'=NEW.capability_key;
 max_duration=COALESCE((cap #>> '{approvalScope,maxDurationSeconds}')::bigint,(cap #>> '{approvalScope,limits,durationSeconds}')::bigint,86400);
 max_count=COALESCE((cap #>> '{approvalScope,maxEffects}')::bigint,(cap #>> '{approvalScope,limits,maxEffects}')::bigint,100);
 lifetime_choices=COALESCE(cap #> '{approvalScope,allowedLifetimes}','["ROOT_RUN"]'::jsonb);
 IF cap IS NULL OR NEW.max_effects>max_count OR NEW.expires_at>clock_timestamp()+make_interval(secs=>max_duration)
  OR NOT (lifetime_choices ? NEW.scope_lifetime) THEN RAISE EXCEPTION 'integration approval scope exceeds pinned policy'; END IF;
 RETURN NEW;
END $scope_insert$;
-- +goose StatementEnd
CREATE TRIGGER integration_approval_scopes_guard_insert BEFORE INSERT ON control_plane.integration_approval_scopes
 FOR EACH ROW EXECUTE FUNCTION control_plane.guard_integration_approval_scope_insert();

-- Cross-run consent переживает обычный terminal исходного root; ROOT_RUN — нет.
-- +goose StatementBegin
DO $root_lifetime$
DECLARE source text; before text := 'WHERE root_run_id=OLD.id AND revoked_at IS NULL';
BEGIN
 SELECT pg_get_functiondef('control_plane.revoke_integration_approval_scopes()'::regprocedure) INTO source;
 IF (length(source)-length(replace(source,before,'')))/length(before)<>1 THEN RAISE EXCEPTION 'integration revoke predecessor changed'; END IF;
 EXECUTE replace(source,before,before || ' AND scope_lifetime=''ROOT_RUN''');
END $root_lifetime$;
-- +goose StatementEnd
REVOKE ALL ON FUNCTION control_plane.guard_integration_approval_scope_insert() FROM PUBLIC;
-- Versioned object checks сохраняют personal binding, prerequisite observations
-- и свежую provider authorization независимо от выбранной human policy.
-- +goose StatementBegin
DO $personal_policy$
DECLARE source text;
 before text := $old$          AND (
            (NEW.resource_permission_profile=''$old$;
 after text := $new$          AND control_plane.integration_declared_policy_allowed(connection.id,invocation.capability_key,invocation.operation,
            invocation.risk,invocation.resource_kind,invocation.approval_policy,invocation.bounded_input)
          AND (
            (NEW.resource_permission_profile='GITLAB_SCOPED_RESOURCE_V2'
             AND connection.definition_key='gitlab' AND invocation.resource_kind='GITLAB_SCOPE'
             AND invocation.operation=invocation.capability_key AND invocation.capability_key<>'gitlab.scope.health.read'
             AND binding.verified_capabilities @> ARRAY['gitlab.scope.health.read']::text[]
             AND NOT binding.denied_capabilities && ARRAY['gitlab.scope.health.read']::text[])
            OR (NEW.resource_permission_profile=''
             AND NOT(connection.definition_key='gitlab' AND invocation.resource_kind='GITLAB_SCOPE' AND invocation.capability_key<>'gitlab.scope.health.read')$new$;
 each_before text := 'invocation.approval_policy=''HUMAN_EACH_EFFECT''';
 none_before text := 'invocation.approval_policy=''NONE''';
 policy_after text := $declared$(EXISTS(SELECT 1 FROM jsonb_array_elements(control_plane.integration_pinned_capabilities(connection.id)) cap
               WHERE cap->>'key'=invocation.capability_key AND cap ? 'approvalScope') AND
              control_plane.integration_declared_policy_allowed(connection.id,invocation.capability_key,invocation.operation,
               invocation.risk,invocation.resource_kind,invocation.approval_policy,invocation.bounded_input))$declared$;
BEGIN
 SELECT pg_get_functiondef('control_plane.guard_personal_invocation_credential()'::regprocedure) INTO source;
 IF (length(source)-length(replace(source,before,'')))/length(before)<>1
  OR (length(source)-length(replace(source,each_before,'')))/length(each_before)<>3
  OR (length(source)-length(replace(source,none_before,'')))/length(none_before)<>3
 THEN RAISE EXCEPTION 'personal invocation policy predecessor changed'; END IF;
 source=replace(source,before,after);
 source=replace(source,each_before,'('||each_before||' OR '||policy_after||')');
 source=replace(source,none_before,'('||none_before||' OR '||policy_after||')');
 EXECUTE source;
END $personal_policy$;
-- +goose StatementEnd
RESET ROLE;
-- +goose Down
-- +goose StatementBegin
DO $$ BEGIN RAISE EXCEPTION 'integration resource policy migration is forward-only'; END $$;
-- +goose StatementEnd
